import { defineConfig } from 'vite';
import { resolve } from 'node:path';
import { PROJECTS } from './src/content.ts';

const r = (p: string) => resolve(import.meta.dirname, p);

// Every HTML entry. The /work and /about pages are generated by
// scripts/build-pages.ts (runs as predev / prebuild) before Vite sees them.
const input: Record<string, string> = {
  game: r('index.html'),
  notFound: r('404.html'),
  work: r('work/index.html'),
  about: r('about/index.html'),
};
for (const p of PROJECTS) input[`work-${p.slug}`] = r(`work/${p.slug}/index.html`);

export default defineConfig({
  appType: 'mpa',
  build: { rollupOptions: { input } },
});
